        if(p==null){check(coin==1&&m.privateView(A).deck().equals(deck)&&m.activePokemonView(A).topCardId().equals("ditto")&&m.currentPlayer().equals(B),"Tails inspected/shuffled/replaced or did not finish");continue;}
